for rec in records:
    if '-' in rec.name:
        prefix = rec.name.rsplit('-', 1)[0]
        all_mos = env['mrp.production'].search([
            ('name', 'like', prefix + '%')
        ], order='id asc')
        if len(all_mos) > 0:
            first_mo = all_mos[0]
            if not first_mo.x_studio_nbr_original_1:
                first_mo.write({'x_studio_nbr_original_1': first_mo.x_studio_nbr})
            original = first_mo.x_studio_nbr_original_1
            total = len(all_mos)
            if total > 1 and original:
                new_nbr = original / total
                mos_to_update = all_mos.filtered(lambda mo: mo.x_studio_nbr != new_nbr)
                if mos_to_update:
                    mos_to_update.write({'x_studio_nbr': new_nbr})
                    rec.message_post(body="✅ %s OF mis à jour: %s → %s" % (len(mos_to_update), original, new_nbr))
    elif rec.x_studio_nbr and not rec.x_studio_nbr_original_1:
        rec.write({'x_studio_nbr_original_1': rec.x_studio_nbr})

VENTES_FOLDER_ID = env['documents.document'].search([('name', '=', 'Ventes'), ('type', '=', 'folder')], limit=1).id
for order in records:
    attachments_order = env['ir.attachment'].search([
        ('res_model', '=', 'sale.order'),
        ('res_id', '=', order.id),
        ('res_field', '=', 'x_studio_plan_gnral')
    ])
    attachments_lines = env['ir.attachment']
    for line in order.order_line:
        if line.x_studio_plan_ligne_attachment:
            attachments_lines = attachments_lines | line.x_studio_plan_ligne_attachment
    all_attachments = attachments_order | attachments_lines
    if all_attachments:
        tag_client = env['documents.tag'].search([
            ('name', '=', order.partner_id.name)
        ], limit=1)
        if not tag_client:
            tag_client = env['documents.tag'].create({
                'name': order.partner_id.name
            })
        tag_plan = env['documents.tag'].search([
            ('name', '=', 'Plan de fabrication')
        ], limit=1)
        if not tag_plan:
            tag_plan = env['documents.tag'].create({
                'name': 'Plan de fabrication'
            })
        for att in all_attachments:
            existing_doc = env['documents.document'].search([
                ('attachment_id', '=', att.id)
            ], limit=1)
            if not existing_doc:
                if att.res_field == 'x_studio_plan_gnral':
                    type_plan = "Plan général"
                else:
                    type_plan = "Plan ligne"
                doc_name = "[%s] %s - %s" % (order.name, type_plan, att.name)
                env['documents.document'].create({
                    'attachment_id': att.id,
                    'folder_id': VENTES_FOLDER_ID,
                    'name': doc_name,
                    'res_model': 'sale.order',
                    'res_id': order.id,
                    'partner_id': order.partner_id.id,
                    'tag_ids': [Command.set([tag_client.id, tag_plan.id])]
                })

for record in records:
    if record.display_type:
        continue
    if not record.product_id:
        continue
    product_taxes = record.product_id.taxes_id.filtered(
        lambda t: t.company_id == record.company_id
    )
    if not product_taxes:
        continue
    fiscal_position = record.order_id.fiscal_position_id
    if fiscal_position:
        product_taxes = fiscal_position.map_tax(product_taxes)
    if record.tax_ids != product_taxes:
        record.write({'tax_ids': [Command.set(product_taxes.ids)]})

# Étape de la tâche Commande Pierres selon les OF : recalcul DIFFÉRÉ en fin de transaction (une passe par tâche,
# au lieu d'un balayage de tous les OF de la tâche à chaque changement d'état de chaque OF).
_tids = set(records.mapped('x_studio_tche_commande_pierre').ids)
if _tids:
    _d = env.cr.precommit.data
    if 'maq_etape_of' not in _d:
        _d['maq_etape_of'] = set()
        def _maq_etape_of():
            _ids = env.cr.precommit.data.pop('maq_etape_of', set())
            TASKS = env['project.task'].browse(sorted(_ids)).exists()
            STAGES = [113, 119, 114, 115, 116, 117, 118]
            for task in TASKS:
                if not task:
                    continue
                so_recs = task.x_studio_devis_commandes_1
                of_recs = task.x_studio_of
                idx = 0
                if so_recs:
                    idx = 1
                has_sale = False
                has_deliv = False
                has_inv = False
                for s in so_recs:
                    if s.state == 'sale':
                        has_sale = True
                    if s.delivery_status == 'full':
                        has_deliv = True
                    if s.invoice_status == 'invoiced':
                        has_inv = True
                of_total = 0
                of_done = 0
                of_open = 0
                of_inprog = False
                for o in of_recs:
                    of_total += 1
                    if o.state in ('confirmed', 'progress', 'to_close'):
                        of_inprog = True
                    if o.state == 'done':
                        of_done += 1
                    if o.state not in ('done', 'cancel'):
                        of_open += 1
                if has_sale and idx < 2:
                    idx = 2
                if of_inprog and idx < 3:
                    idx = 3
                if of_total > 0 and of_open == 0 and of_done > 0 and idx < 4:
                    idx = 4
                if has_deliv and idx < 5:
                    idx = 5
                if has_inv and idx < 6:
                    idx = 6
                cur = 0
                if task.stage_id and task.stage_id.id in STAGES:
                    cur = STAGES.index(task.stage_id.id)
                if idx > cur:
                    task.write({'stage_id': STAGES[idx]})
            env.flush_all()
        env.cr.precommit.add(_maq_etape_of)
    _d['maq_etape_of'].update(_tids)

# UdF selon le libelle de variante du produit : (Tonne), (Forfait), (Heure),
# (au Tour), (par jours) — posee uniquement si l'unite de mesure de la ligne
# ne porte pas deja cette unite, et sans ecraser une UdF saisie manuellement.
MAP = [('(tonne', 'Tonne'), ('(forfait', 'Forfait'), ('(heure', 'Heure'),
       ('au tour)', 'Tour'), ('par jours)', 'Jours'), ('par jour)', 'Jours')]
UOM_EQ = {'tonne': 'Tonne', 'forfait': 'Forfait', 'hours': 'Heure',
          'heure': 'Heure', 'heures': 'Heure', 'jours': 'Jours', 'jour': 'Jours',
          'unité': 'Unité(s)', 'unités': 'Unité(s)', 'm²': 'm²', 'm³': 'm³'}
for rec in records:
    if rec.x_studio_udf:
        continue
    name = (rec.product_id.display_name or rec.name or '').lower()
    uom = (rec.product_uom_id.name or '').strip().lower()
    cible = None
    for motif, udf in MAP:
        if motif in name:
            cible = udf
            break
    if cible and UOM_EQ.get(uom) != cible:
        rec.write({'x_studio_udf': cible})
